(()=>{
  const lang=document.documentElement.lang==='es'?'es':'ca';
  const slug=location.pathname.split('/').filter(Boolean).pop()||'';
  const key=({faqs:'faq','preguntas-frecuentes':'faq',manifest:'manifest',manifiesto:'manifest',privacitat:'privacy',privacidad:'privacy',cookies:'cookies',legal:'legal','aviso-legal':'legal',contacte:'contact',contacto:'contact'})[slug]||'faq';
  const legalCa={eyebrow:'Legal',title:'Avís legal i condicions d’ús',intro:'Última actualització: 13 d’agost de 2026.',sections:[
    ['1. Identificació del titular','En compliment de la Llei 34/2002, d’11 de juliol, de serveis de la societat de la informació i del comerç electrònic, s’informa que aquest lloc web és titularitat de:<br><br><strong>Titular:</strong> Martí Ruiz Andújar<br><strong>NIF:</strong> 47278506M<br><strong>Correu electrònic:</strong> <a href="mailto:hola@uncartell.cat">hola@uncartell.cat</a><br><strong>Nom del servei:</strong> uncartell.cat<br><strong>Domini:</strong> <a href="https://uncartell.cat/">https://uncartell.cat</a><br><br>En endavant, el “titular” o “uncartell.cat”.'],
    ['2. Objecte del servei','uncartell.cat ofereix eines digitals per crear, editar, personalitzar, desar i descarregar cartells, cartes, menús, tarifes, codis QR i altres recursos gràfics.<br><br>Determinades funcionalitats es poden utilitzar sense registre. Altres poden requerir la creació d’un compte o l’activació d’un pla concret.<br><br>Les característiques, els formats, els límits i la disponibilitat de cada funcionalitat són els indicats al web en cada moment.'],
    ['3. Acceptació de les condicions','L’accés i l’ús d’uncartell.cat impliquen l’acceptació d’aquestes condicions.<br><br>Si una persona no hi està d’acord, s’ha d’abstenir d’utilitzar el servei. Quan una funcionalitat tingui condicions específiques, aquestes s’aplicaran complementàriament.<br><br>La contractació futura de serveis de pagament quedarà subjecta a unes condicions de contractació específiques, que s’hauran de mostrar i acceptar abans de completar el pagament.'],
    ['4. Condicions d’accés i ús','La persona usuària es compromet a utilitzar el servei de manera lícita, diligent i respectuosa amb els drets de tercers.<br><br>No està permès:<ul><li>Revendre o redistribuir les plantilles o els recursos editables d’uncartell.cat.</li><li>Copiar o explotar sistemàticament el catàleg, la interfície o el funcionament del servei.</li><li>Fer descàrregues automatitzades o massives, extreure continguts o eludir els límits tècnics establerts.</li><li>Presentar les plantilles, el catàleg, el codi o el sistema d’edició com a propis.</li><li>Utilitzar el servei per crear o difondre continguts il·lícits, fraudulents, enganyosos, discriminatoris o que vulnerin drets de tercers.</li><li>Introduir programari maliciós, intentar accedir a dades alienes o comprometre la seguretat o disponibilitat del servei.</li><li>Utilitzar el servei d’una manera que pugui perjudicar altres persones usuàries o la infraestructura d’uncartell.cat.</li></ul>El titular pot limitar o suspendre l’accés quan existeixin indicis raonables de frau, abús, risc de seguretat o incompliment d’aquestes condicions.'],
    ['5. Comptes d’usuari','La persona usuària és responsable de proporcionar informació correcta, mantenir la confidencialitat dels seus mitjans d’accés i comunicar qualsevol ús no autoritzat del compte.<br><br>No es poden crear comptes utilitzant dades falses ni suplantant terceres persones.<br><br>La persona usuària pot sol·licitar l’eliminació del compte pels mitjans habilitats al servei. L’eliminació estarà subjecta als terminis tècnics i legals indicats a la Política de privacitat.'],
    ['6. Llicència d’ús dels documents generats','La persona usuària pot utilitzar els documents finals generats amb uncartell.cat per a finalitats personals, professionals o comercials pròpies, incloent-hi la impressió, publicació, exposició o distribució vinculada a la seva activitat.<br><br>Aquesta autorització afecta exclusivament el resultat final generat. No comporta la cessió dels drets sobre les plantilles, els components gràfics, la interfície, el codi, el catàleg ni el sistema d’edició d’uncartell.cat.<br><br>No es permet:<ul><li>Comercialitzar les plantilles o els arxius editables com a productes independents.</li><li>Redistribuir-los com a banc de recursos.</li><li>Crear un servei competidor basat substancialment en els recursos o el funcionament d’uncartell.cat.</li><li>Eliminar o alterar marques d’aigua o limitacions del pla mitjançant procediments no autoritzats.</li></ul>'],
    ['7. Continguts aportats per les persones usuàries','La persona usuària conserva els drets sobre els textos, marques, logotips, fotografies i altres fitxers que incorpori als seus projectes.<br><br>En introduir o pujar aquests continguts, declara que:<ul><li>N’és titular o disposa dels permisos necessaris.</li><li>El seu ús no vulnera drets de propietat intel·lectual o industrial, protecció de dades, imatge, honor, intimitat o altres drets de tercers.</li><li>Els continguts són lícits i no contenen programari maliciós.</li></ul>La persona usuària concedeix a uncartell.cat una autorització limitada, no exclusiva, revocable i temporal per allotjar, processar, adaptar tècnicament, reproduir i mostrar aquests continguts únicament en la mesura necessària per prestar el servei.<br><br>uncartell.cat pot bloquejar o retirar continguts quan tingui coneixement efectiu del seu caràcter il·lícit o d’una possible vulneració de drets.'],
    ['8. Obligació de revisar els documents','Les eines d’uncartell.cat faciliten la composició gràfica de documents, però no substitueixen l’assessorament jurídic, tècnic, sanitari, administratiu o professional que pugui requerir cada activitat.<br><br>Abans d’imprimir, publicar, compartir o instal·lar qualsevol document, correspon a la persona usuària comprovar:<ul><li>L’exactitud dels textos, preus, dates, horaris i dades de contacte.</li><li>Les dimensions, marges, colors, llegibilitat i qualitat del resultat.</li><li>El funcionament dels enllaços i codis QR.</li><li>La vigència, disponibilitat pública i permisos dels documents enllaçats.</li><li>Els drets d’ús de les fotografies, marques, logotips i altres continguts incorporats.</li><li>El compliment de la normativa aplicable sobre preus, consum, al·lèrgens, accessibilitat, seguretat, comerç, publicitat, senyalització o qualsevol altra matèria sectorial.</li></ul>uncartell.cat no certifica que un document generat compleixi automàticament totes les obligacions aplicables a cada activitat, establiment o territori.'],
    ['9. Codis QR i enllaços externs','Els codis QR generats reprodueixen l’adreça introduïda per la persona usuària.<br><br>uncartell.cat no controla necessàriament el contingut de destinació ni en garanteix la disponibilitat, seguretat, legalitat o permanència.<br><br>Correspon a la persona usuària verificar que:<ul><li>L’adreça és correcta i funciona.</li><li>El contingut és accessible per al públic destinatari.</li><li>No es publica informació personal indegudament.</li><li>Disposa dels permisos necessaris per compartir-lo.</li><li>El codi funciona abans d’imprimir-lo o distribuir-lo.</li></ul>La generació d’un codi QR no garanteix que l’enllaç de destinació continuï disponible en el futur.'],
    ['10. Disponibilitat i conservació dels projectes','Es treballa perquè el servei sigui segur i estigui disponible, però no es pot garantir un funcionament ininterromput, lliure d’errors o compatible amb tots els dispositius, navegadors, impressores o programes.<br><br>El servei pot quedar temporalment interromput per manteniment, actualitzacions, incidències tècniques, actuacions de proveïdors o causes alienes al control raonable del titular.<br><br>La possibilitat de desar projectes no constitueix un servei d’arxivament permanent. Es recomana conservar una còpia local dels documents importants.'],
    ['11. Responsabilitat','El titular respondrà dels danys directes que li siguin legalment imputables.<br><br>En la mesura permesa per la normativa aplicable, no serà responsable dels perjudicis derivats de:<ul><li>Informació incorrecta o incompleta introduïda per la persona usuària.</li><li>La manca de revisió dels documents abans de publicar-los o imprimir-los.</li><li>L’ús dels documents en contra de la normativa aplicable.</li><li>L’ús no autoritzat de marques, fotografies o continguts aportats per la persona usuària.</li><li>La configuració o qualitat d’equips, navegadors, impressores o serveis de tercers.</li><li>La indisponibilitat, modificació o inseguretat d’enllaços i continguts externs.</li><li>Incidències provocades per tercers, atacs informàtics inevitables o causes de força major.</li></ul>Cap disposició d’aquestes condicions exclou els drets irrenunciables de les persones consumidores ni limita responsabilitats que legalment no puguin ser excloses.'],
    ['12. Propietat intel·lectual i industrial','La marca uncartell.cat, la interfície, el codi, l’estructura del servei, la selecció i organització del catàleg, les plantilles i els dissenys originals estan protegits per la normativa de propietat intel·lectual i industrial.<br><br>Els recursos de tercers es regeixen per les seves llicències respectives.<br><br>La disponibilitat pública del servei no comporta cap cessió de drets més enllà de la llicència d’ús expressament prevista en aquestes condicions.'],
    ['13. Serveis de tercers','El web pot utilitzar serveis de tercers per a l’autenticació, allotjament, bases de dades, emmagatzematge, comunicacions o pagaments.<br><br>Aquests serveis poden estar subjectes a les seves pròpies condicions i polítiques. uncartell.cat no respon dels continguts, canvis o incidències produïts exclusivament en serveis externs, sens perjudici de les responsabilitats que li corresponguin legalment com a responsable del servei o del tractament de dades.'],
    ['14. Comunicació d’infraccions','Per comunicar continguts presumptament il·lícits, vulneracions de drets o problemes de seguretat, es pot escriure a <a href="mailto:hola@uncartell.cat">hola@uncartell.cat</a>.<br><br>La comunicació ha d’identificar el contingut afectat, explicar el motiu de la reclamació i aportar la informació necessària per valorar-la.'],
    ['15. Modificacions','El titular pot modificar les eines, els límits, els plans o aquestes condicions per adaptar-los a canvis tècnics, comercials o normatius.<br><br>Els canvis rellevants s’informaran al web i, quan afectin persones registrades o serveis contractats, pels mitjans legalment exigibles.<br><br>Les modificacions no s’aplicaran retroactivament quan perjudiquin drets adquirits.'],
    ['16. Legislació aplicable i jurisdicció','Aquestes condicions es regeixen per la legislació espanyola i europea aplicable.<br><br>Les controvèrsies se sotmetran als jutjats i tribunals que corresponguin legalment. Quan la persona usuària tingui la condició de consumidora, es respectarà el seu fur legal i no se li imposarà una jurisdicció diferent de la prevista per la normativa de consum.']
  ]};
  const legalEs={eyebrow:'Legal',title:'Aviso legal y condiciones de uso',intro:'Última actualización: 13 de agosto de 2026.',sections:legalCa.sections.map(([heading,body])=>[heading,body])};
  legalEs.sections=[
    ['1. Identificación del titular','En cumplimiento de la Ley 34/2002, de 11 de julio, de servicios de la sociedad de la información y del comercio electrónico, se informa de que este sitio web es titularidad de:<br><br><strong>Titular:</strong> Martí Ruiz Andújar<br><strong>NIF:</strong> 47278506M<br><strong>Correo electrónico:</strong> <a href="mailto:hola@uncartel.es">hola@uncartel.es</a><br><strong>Nombre del servicio:</strong> uncartel.es<br><strong>Dominio:</strong> <a href="https://uncartel.es/">https://uncartel.es</a><br><br>En adelante, el “titular” o “uncartel.es”.'],
    ['2. Objeto del servicio','uncartel.es ofrece herramientas digitales para crear, editar, personalizar, guardar y descargar carteles, cartas, menús, tarifas, códigos QR y otros recursos gráficos.<br><br>Determinadas funcionalidades pueden utilizarse sin registro. Otras pueden requerir la creación de una cuenta o la activación de un plan concreto.<br><br>Las características, formatos, límites y disponibilidad de cada funcionalidad son los indicados en la web en cada momento.'],
    ['3. Aceptación de las condiciones','El acceso y uso de uncartel.es implican la aceptación de estas condiciones.<br><br>Si una persona no está de acuerdo, deberá abstenerse de utilizar el servicio. Cuando una funcionalidad tenga condiciones específicas, estas se aplicarán de forma complementaria.<br><br>La futura contratación de servicios de pago quedará sujeta a condiciones de contratación específicas, que deberán mostrarse y aceptarse antes de completar el pago.'],
    ['4. Condiciones de acceso y uso','La persona usuaria se compromete a utilizar el servicio de forma lícita, diligente y respetuosa con los derechos de terceros.<br><br>No está permitido:<ul><li>Revender o redistribuir las plantillas o recursos editables de uncartel.es.</li><li>Copiar o explotar sistemáticamente el catálogo, la interfaz o el funcionamiento del servicio.</li><li>Realizar descargas automatizadas o masivas, extraer contenidos o eludir los límites técnicos establecidos.</li><li>Presentar las plantillas, el catálogo, el código o el sistema de edición como propios.</li><li>Utilizar el servicio para crear o difundir contenidos ilícitos, fraudulentos, engañosos, discriminatorios o que vulneren derechos de terceros.</li><li>Introducir software malicioso, intentar acceder a datos ajenos o comprometer la seguridad o disponibilidad del servicio.</li><li>Utilizar el servicio de forma que pueda perjudicar a otras personas usuarias o a la infraestructura de uncartel.es.</li></ul>El titular podrá limitar o suspender el acceso cuando existan indicios razonables de fraude, abuso, riesgo de seguridad o incumplimiento de estas condiciones.'],
    ['5. Cuentas de usuario','La persona usuaria es responsable de proporcionar información correcta, mantener la confidencialidad de sus medios de acceso y comunicar cualquier uso no autorizado de la cuenta.<br><br>No se pueden crear cuentas utilizando datos falsos ni suplantando a terceras personas.<br><br>La persona usuaria puede solicitar la eliminación de la cuenta mediante los medios habilitados en el servicio. La eliminación estará sujeta a los plazos técnicos y legales indicados en la Política de privacidad.'],
    ['6. Licencia de uso de los documentos generados','La persona usuaria puede utilizar los documentos finales generados con uncartel.es para fines personales, profesionales o comerciales propios, incluyendo su impresión, publicación, exposición o distribución vinculada a su actividad.<br><br>Esta autorización afecta exclusivamente al resultado final generado. No implica la cesión de derechos sobre las plantillas, componentes gráficos, interfaz, código, catálogo ni sistema de edición de uncartel.es.<br><br>No se permite:<ul><li>Comercializar las plantillas o archivos editables como productos independientes.</li><li>Redistribuirlos como banco de recursos.</li><li>Crear un servicio competidor basado sustancialmente en los recursos o funcionamiento de uncartel.es.</li><li>Eliminar o alterar marcas de agua o limitaciones del plan mediante procedimientos no autorizados.</li></ul>'],
    ['7. Contenidos aportados por las personas usuarias','La persona usuaria conserva los derechos sobre los textos, marcas, logotipos, fotografías y demás archivos que incorpore a sus proyectos.<br><br>Al introducir o subir estos contenidos, declara que:<ul><li>Es su titular o dispone de los permisos necesarios.</li><li>Su uso no vulnera derechos de propiedad intelectual o industrial, protección de datos, imagen, honor, intimidad u otros derechos de terceros.</li><li>Los contenidos son lícitos y no contienen software malicioso.</li></ul>La persona usuaria concede a uncartel.es una autorización limitada, no exclusiva, revocable y temporal para alojar, procesar, adaptar técnicamente, reproducir y mostrar estos contenidos únicamente en la medida necesaria para prestar el servicio.<br><br>uncartel.es podrá bloquear o retirar contenidos cuando tenga conocimiento efectivo de su carácter ilícito o de una posible vulneración de derechos.'],
    ['8. Obligación de revisar los documentos','Las herramientas de uncartel.es facilitan la composición gráfica de documentos, pero no sustituyen el asesoramiento jurídico, técnico, sanitario, administrativo o profesional que pueda requerir cada actividad.<br><br>Antes de imprimir, publicar, compartir o instalar cualquier documento, corresponde a la persona usuaria comprobar:<ul><li>La exactitud de textos, precios, fechas, horarios y datos de contacto.</li><li>Las dimensiones, márgenes, colores, legibilidad y calidad del resultado.</li><li>El funcionamiento de enlaces y códigos QR.</li><li>La vigencia, disponibilidad pública y permisos de los documentos enlazados.</li><li>Los derechos de uso de fotografías, marcas, logotipos y demás contenidos incorporados.</li><li>El cumplimiento de la normativa aplicable sobre precios, consumo, alérgenos, accesibilidad, seguridad, comercio, publicidad, señalización o cualquier otra materia sectorial.</li></ul>uncartel.es no certifica que un documento generado cumpla automáticamente todas las obligaciones aplicables a cada actividad, establecimiento o territorio.'],
    ['9. Códigos QR y enlaces externos','Los códigos QR generados reproducen la dirección introducida por la persona usuaria.<br><br>uncartel.es no controla necesariamente el contenido de destino ni garantiza su disponibilidad, seguridad, legalidad o permanencia.<br><br>Corresponde a la persona usuaria verificar que:<ul><li>La dirección es correcta y funciona.</li><li>El contenido es accesible para el público destinatario.</li><li>No se publica información personal indebidamente.</li><li>Dispone de los permisos necesarios para compartirlo.</li><li>El código funciona antes de imprimirlo o distribuirlo.</li></ul>La generación de un código QR no garantiza que el enlace de destino continúe disponible en el futuro.'],
    ['10. Disponibilidad y conservación de los proyectos','Se trabaja para que el servicio sea seguro y esté disponible, pero no se puede garantizar un funcionamiento ininterrumpido, libre de errores o compatible con todos los dispositivos, navegadores, impresoras o programas.<br><br>El servicio puede quedar temporalmente interrumpido por mantenimiento, actualizaciones, incidencias técnicas, actuaciones de proveedores o causas ajenas al control razonable del titular.<br><br>La posibilidad de guardar proyectos no constituye un servicio de archivo permanente. Se recomienda conservar una copia local de los documentos importantes.'],
    ['11. Responsabilidad','El titular responderá de los daños directos que le sean legalmente imputables.<br><br>En la medida permitida por la normativa aplicable, no será responsable de los perjuicios derivados de:<ul><li>Información incorrecta o incompleta introducida por la persona usuaria.</li><li>La falta de revisión de los documentos antes de publicarlos o imprimirlos.</li><li>El uso de los documentos contrario a la normativa aplicable.</li><li>El uso no autorizado de marcas, fotografías o contenidos aportados por la persona usuaria.</li><li>La configuración o calidad de equipos, navegadores, impresoras o servicios de terceros.</li><li>La indisponibilidad, modificación o inseguridad de enlaces y contenidos externos.</li><li>Incidencias provocadas por terceros, ataques informáticos inevitables o causas de fuerza mayor.</li></ul>Ninguna disposición de estas condiciones excluye los derechos irrenunciables de las personas consumidoras ni limita responsabilidades que legalmente no puedan excluirse.'],
    ['12. Propiedad intelectual e industrial','La marca uncartel.es, la interfaz, el código, la estructura del servicio, la selección y organización del catálogo, las plantillas y los diseños originales están protegidos por la normativa de propiedad intelectual e industrial.<br><br>Los recursos de terceros se rigen por sus respectivas licencias.<br><br>La disponibilidad pública del servicio no implica ninguna cesión de derechos más allá de la licencia de uso expresamente prevista en estas condiciones.'],
    ['13. Servicios de terceros','La web puede utilizar servicios de terceros para autenticación, alojamiento, bases de datos, almacenamiento, comunicaciones o pagos.<br><br>Estos servicios pueden estar sujetos a sus propias condiciones y políticas. uncartel.es no responde de los contenidos, cambios o incidencias producidos exclusivamente en servicios externos, sin perjuicio de las responsabilidades que le correspondan legalmente como responsable del servicio o del tratamiento de datos.'],
    ['14. Comunicación de infracciones','Para comunicar contenidos presuntamente ilícitos, vulneraciones de derechos o problemas de seguridad, puede escribirse a <a href="mailto:hola@uncartel.es">hola@uncartel.es</a>.<br><br>La comunicación deberá identificar el contenido afectado, explicar el motivo de la reclamación y aportar la información necesaria para valorarla.'],
    ['15. Modificaciones','El titular puede modificar las herramientas, límites, planes o estas condiciones para adaptarlos a cambios técnicos, comerciales o normativos.<br><br>Los cambios relevantes se informarán en la web y, cuando afecten a personas registradas o servicios contratados, mediante los medios legalmente exigibles.<br><br>Las modificaciones no se aplicarán retroactivamente cuando perjudiquen derechos adquiridos.'],
    ['16. Legislación aplicable y jurisdicción','Estas condiciones se rigen por la legislación española y europea aplicable.<br><br>Las controversias se someterán a los juzgados y tribunales que correspondan legalmente. Cuando la persona usuaria tenga la condición de consumidora, se respetará su fuero legal y no se le impondrá una jurisdicción distinta de la prevista por la normativa de consumo.']
  ];
  const privacyCa={eyebrow:'Legal',title:'Política de privacitat',intro:'Última actualització: 13 d’agost de 2026.',sections:[
    ['1. Responsable del tractament','<strong>Responsable:</strong> Martí Ruiz Andújar<br><strong>NIF:</strong> 47278506M<br><strong>Correu electrònic:</strong> <a href="mailto:hola@uncartell.cat">hola@uncartell.cat</a><br><strong>Lloc web:</strong> <a href="https://uncartell.cat/">https://uncartell.cat</a><br><br>No s’ha designat delegat de protecció de dades perquè, atenent la naturalesa actual del servei i dels tractaments efectuats, no és legalment obligatori.'],
    ['2. Normativa aplicable','Les dades personals es tracten d’acord amb el Reglament (UE) 2016/679, general de protecció de dades —RGPD—, la Llei orgànica 3/2018, de protecció de dades personals i garantia dels drets digitals —LOPDGDD—, i la resta de normativa aplicable.'],
    ['3. Dades que podem tractar','Segons l’ús que facis del servei, podem tractar les categories de dades següents:<h3>Dades del compte</h3><ul><li>Nom o àlies.</li><li>Adreça electrònica.</li><li>Identificador intern d’usuari.</li><li>Mètode d’accés utilitzat.</li><li>Pla activat i dates associades.</li><li>Preferències i configuració del compte.</li></ul><h3>Dades d’ús i seguretat</h3><ul><li>Recompte de descàrregues.</li><li>Registre d’accessos, errors i incidències.</li><li>Adreça IP i informació tècnica del dispositiu o navegador quan sigui necessària per a la seguretat i el funcionament.</li><li>Acceptacions de condicions i preferències de privacitat.</li></ul><h3>Projectes i continguts</h3><ul><li>Textos, configuracions, colors i altres dades dels projectes.</li><li>Logotips, fotografies o fitxers que decideixis pujar o desar.</li><li>Enllaços introduïts per generar codis QR.</li></ul>Els enllaços utilitzats per generar un QR poden contenir informació personal. No hi introdueixis informació que no vulguis fer accessible a les persones que rebin el codi.<h3>Consultes</h3><ul><li>Nom.</li><li>Adreça electrònica.</li><li>Contingut del missatge.</li><li>Informació addicional que decideixis proporcionar.</li></ul><h3>Dades de pagament</h3>Si s’activen plans de pagament, el proveïdor de pagaments tractarà les dades necessàries per gestionar l’operació. uncartell.cat no hauria de rebre ni conservar el número complet de la targeta.<br><br>Podem rebre informació sobre l’estat del pagament, l’import, la moneda, l’identificador de l’operació i les dades necessàries per a la facturació i el compliment d’obligacions legals.'],
    ['4. Origen de les dades','Les dades s’obtenen:<ul><li>Directament de la persona usuària quan crea un compte, completa un formulari o introdueix continguts.</li><li>Del proveïdor d’autenticació quan s’utilitza l’accés amb Google.</li><li>Automàticament durant l’ús del servei, quan és necessari per al funcionament, la seguretat o el control dels límits.</li><li>Del proveïdor de pagaments, si es contracta un servei de pagament.</li></ul>Quan utilitzes l’accés amb Google, només rebem les dades bàsiques autoritzades necessàries per identificar i crear el compte, habitualment el nom, l’adreça electrònica, la imatge de perfil i l’identificador del compte.<br><br>Aquest accés no permet llegir Gmail, Google Drive, els contactes ni altres continguts del compte de Google.'],
    ['5. Finalitats i bases jurídiques','<div class="u-legal-table"><table><thead><tr><th>Tractament</th><th>Finalitat</th><th>Base jurídica</th></tr></thead><tbody><tr><td>Creació i gestió del compte</td><td>Identificar la persona usuària, permetre l’accés i gestionar el pla</td><td>Execució de la relació contractual o aplicació de mesures sol·licitades</td></tr><tr><td>Prestació de les eines</td><td>Crear, editar, desar, recuperar i descarregar projectes</td><td>Execució del servei sol·licitat</td></tr><tr><td>Control de descàrregues i funcionalitats</td><td>Aplicar els límits corresponents a cada pla</td><td>Execució del servei i interès legítim en evitar abusos</td></tr><tr><td>Seguretat i prevenció del frau</td><td>Protegir comptes, sistemes i altres persones usuàries</td><td>Interès legítim i, quan correspongui, obligació legal</td></tr><tr><td>Atenció de consultes</td><td>Respondre preguntes, incidències o sol·licituds</td><td>Consentiment, mesures precontractuals o interès legítim</td></tr><tr><td>Comunicacions necessàries</td><td>Enviar avisos sobre el compte, seguretat o canvis essencials</td><td>Execució del servei o obligació legal</td></tr><tr><td>Comunicacions comercials</td><td>Informar sobre novetats, eines o promocions</td><td>Consentiment</td></tr><tr><td>Pagaments i facturació</td><td>Gestionar cobraments, devolucions i obligacions comptables i fiscals</td><td>Execució contractual i obligació legal</td></tr><tr><td>Defensa de reclamacions</td><td>Acreditar operacions i defensar drets</td><td>Interès legítim i compliment d’obligacions legals</td></tr></tbody></table></div>Quan el tractament es basi en el consentiment, el pots retirar en qualsevol moment sense que això afecti la licitud del tractament anterior.<br><br>Quan es basi en l’interès legítim, pots sol·licitar informació sobre la ponderació efectuada i exercir el dret d’oposició.'],
    ['6. Caràcter obligatori de les dades','Els camps marcats com a obligatoris són necessaris per prestar el servei o respondre la sol·licitud.<br><br>Si no els facilites, és possible que no puguis crear un compte, desar projectes, contactar amb nosaltres o utilitzar una funcionalitat determinada.<br><br>No estàs obligat a facilitar dades per utilitzar les funcions que estiguin disponibles sense registre.'],
    ['7. Destinataris i proveïdors','No venem ni cedim dades personals amb finalitats publicitàries.<br><br>Poden accedir a les dades, únicament quan sigui necessari per prestar el servei:<ul><li>Proveïdors d’autenticació i bases de dades, com Supabase.</li><li>Google, quan la persona usuària escull iniciar sessió amb aquest servei.</li><li>Proveïdors d’allotjament, infraestructura, seguretat, correu o recepció de formularis.</li><li>Proveïdors d’emmagatzematge de fitxers, si aquesta funcionalitat està activa.</li><li>Proveïdors de pagament i facturació, quan s’activin serveis de pagament.</li><li>Assessories, professionals jurídics o administracions públiques quan sigui necessari per complir una obligació legal o defensar drets.</li></ul>Els proveïdors que actuen per compte d’uncartell.cat han de tractar les dades d’acord amb les instruccions rebudes, aplicar mesures de seguretat adequades i formalitzar les garanties exigides per la normativa.'],
    ['8. Transferències internacionals','Alguns proveïdors tecnològics poden estar establerts o utilitzar infraestructura fora de l’Espai Econòmic Europeu.<br><br>Quan això impliqui una transferència internacional de dades, s’utilitzaran les garanties previstes pel RGPD, com ara:<ul><li>Una decisió d’adequació de la Comissió Europea.</li><li>El Marc de Privacitat de Dades UE–EUA, quan sigui aplicable.</li><li>Clàusules contractuals tipus aprovades per la Comissió Europea.</li><li>Altres garanties legalment admeses.</li></ul>Pots sol·licitar informació addicional escrivint a <a href="mailto:hola@uncartell.cat">hola@uncartell.cat</a>.'],
    ['9. Terminis de conservació','Les dades es conservaran durant els períodes següents:<ul><li><strong>Compte:</strong> mentre estigui actiu i fins que se’n sol·liciti l’eliminació.</li><li><strong>Projectes desats:</strong> fins que la persona usuària els elimini o elimini el compte.</li><li><strong>Còpies de seguretat:</strong> durant el període tècnic necessari per a la seva rotació i eliminació segura.</li><li><strong>Consultes:</strong> durant el temps necessari per respondre-les i, com a màxim, durant dotze mesos després de tancar-les, llevat que calgui conservar-les per una reclamació.</li><li><strong>Registres de seguretat:</strong> durant el termini necessari per detectar incidències, evitar abusos i defensar el servei.</li><li><strong>Comunicacions comercials:</strong> fins que es retiri el consentiment o se sol·liciti la baixa.</li><li><strong>Factures i dades de pagament:</strong> durant els terminis exigits per la normativa fiscal, comptable i de prevenció del frau.</li><li><strong>Dades vinculades a reclamacions:</strong> mentre pugui existir responsabilitat legal i durant els terminis de prescripció aplicables.</li></ul>Quan finalitzi el termini corresponent, les dades s’eliminaran o quedaran bloquejades i limitades exclusivament al compliment d’obligacions legals.'],
    ['10. Drets de les persones interessades','Pots exercir els drets següents:<ul><li>Accés a les teves dades.</li><li>Rectificació de dades inexactes.</li><li>Supressió de les dades quan legalment correspongui.</li><li>Oposició a determinats tractaments.</li><li>Limitació del tractament.</li><li>Portabilitat de les dades, quan sigui aplicable.</li><li>Retirada del consentiment.</li><li>No ser objecte de decisions basades exclusivament en tractaments automatitzats que produeixin efectes jurídics o similars significatius.</li></ul>Per exercir aquests drets, pots escriure a <a href="mailto:hola@uncartell.cat">hola@uncartell.cat</a>, indicant quin dret vols exercir i aportant la informació necessària per verificar la identitat.<br><br>Només es demanarà documentació identificativa addicional quan existeixin dubtes raonables sobre la identitat de la persona sol·licitant.<br><br>També tens dret a presentar una reclamació davant l’Agència Espanyola de Protecció de Dades: <a href="https://www.aepd.es/">https://www.aepd.es</a>.'],
    ['11. Eliminació del compte','La persona usuària pot eliminar el compte mitjançant les opcions habilitades o sol·licitant-ho a <a href="mailto:hola@uncartell.cat">hola@uncartell.cat</a>.<br><br>L’eliminació comportarà la supressió o anonimització de les dades associades, excepte les que s’hagin de conservar bloquejades per obligació legal, seguretat, prevenció del frau o defensa de reclamacions.<br><br>És responsabilitat de la persona usuària descarregar prèviament els projectes que vulgui conservar.'],
    ['12. Comunicacions comercials','Només enviarem comunicacions comercials quan existeixi una base jurídica vàlida, principalment el consentiment.<br><br>La persona usuària pot donar-se de baixa en qualsevol moment mitjançant l’enllaç incorporat als missatges o escrivint a <a href="mailto:hola@uncartell.cat">hola@uncartell.cat</a>.<br><br>Els avisos imprescindibles sobre seguretat, compte, condicions o funcionament del servei no es consideren comunicacions comercials.'],
    ['13. Menors d’edat','El servei no s’adreça específicament a menors de catorze anys.<br><br>Les persones menors de catorze anys no han de crear un compte ni facilitar dades personals sense l’autorització de qui exerceixi la pàtria potestat o tutela.<br><br>Si es detecten dades facilitades per una persona menor sense autorització, es podran eliminar i bloquejar el compte corresponent.'],
    ['14. Seguretat','S’apliquen mesures tècniques i organitzatives proporcionades al risc per protegir les dades davant la destrucció, pèrdua, alteració, divulgació o accés no autoritzat.<br><br>Tot i això, cap sistema connectat a Internet pot garantir una seguretat absoluta. Si es detecta una violació de seguretat que pugui comportar un risc per als drets de les persones, s’actuarà d’acord amb les obligacions de notificació i comunicació previstes pel RGPD.'],
    ['15. Decisions automatitzades','Actualment no s’adopten decisions basades exclusivament en el tractament automatitzat de dades que produeixin efectes jurídics o afectin significativament les persones usuàries.<br><br>Els controls automàtics de descàrregues, seguretat o accés a funcionalitats es limiten a aplicar les condicions del pla i prevenir usos abusius.'],
    ['16. Enllaços i continguts públics','La persona usuària és responsable de no introduir en projectes, enllaços o codis QR dades personals de tercers sense una base jurídica suficient.<br><br>Quan un document o enllaç es comparteix públicament, pot ser accessible per qualsevol persona que disposi de l’adreça o del codi QR. Correspon a la persona usuària configurar correctament els permisos del servei on estigui allotjat.'],
    ['17. Canvis en aquesta política','Aquesta política es pot actualitzar per adaptar-la a canvis legals, tècnics o funcionals.<br><br>La versió vigent serà sempre la publicada en aquesta pàgina. Quan un canvi sigui rellevant per a les persones registrades, s’informarà mitjançant el web o per correu electrònic.']
  ]};
  const privacyEs={eyebrow:'Legal',title:'Política de privacidad',intro:'Última actualización: 13 de agosto de 2026.',sections:privacyCa.sections.map(([h,b])=>[h,b])};
  privacyEs.sections=[
    ['1. Responsable del tratamiento','<strong>Responsable:</strong> Martí Ruiz Andújar<br><strong>NIF:</strong> 47278506M<br><strong>Correo electrónico:</strong> <a href="mailto:hola@uncartel.es">hola@uncartel.es</a><br><strong>Sitio web:</strong> <a href="https://uncartel.es/">https://uncartel.es</a><br><br>No se ha designado delegado de protección de datos porque, atendiendo a la naturaleza actual del servicio y de los tratamientos efectuados, no es legalmente obligatorio.'],
    ['2. Normativa aplicable','Los datos personales se tratan de acuerdo con el Reglamento (UE) 2016/679, general de protección de datos —RGPD—, la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales —LOPDGDD—, y el resto de normativa aplicable.'],
    ['3. Datos que podemos tratar','Según el uso que hagas del servicio, podemos tratar las siguientes categorías:<h3>Datos de la cuenta</h3><ul><li>Nombre o alias.</li><li>Correo electrónico.</li><li>Identificador interno de usuario.</li><li>Método de acceso utilizado.</li><li>Plan activado y fechas asociadas.</li><li>Preferencias y configuración de la cuenta.</li></ul><h3>Datos de uso y seguridad</h3><ul><li>Recuento de descargas.</li><li>Registro de accesos, errores e incidencias.</li><li>Dirección IP e información técnica cuando sea necesaria para la seguridad y el funcionamiento.</li><li>Aceptaciones de condiciones y preferencias de privacidad.</li></ul><h3>Proyectos y contenidos</h3><ul><li>Textos, configuraciones, colores y otros datos de los proyectos.</li><li>Logotipos, fotografías o archivos que decidas subir o guardar.</li><li>Enlaces introducidos para generar códigos QR.</li></ul>Los enlaces utilizados para generar un QR pueden contener información personal. No introduzcas información que no quieras hacer accesible a quienes reciban el código.<h3>Consultas</h3><ul><li>Nombre.</li><li>Correo electrónico.</li><li>Contenido del mensaje.</li><li>Información adicional que decidas proporcionar.</li></ul><h3>Datos de pago</h3>Si se activan planes de pago, el proveedor de pagos tratará los datos necesarios para gestionar la operación. uncartel.es no debería recibir ni conservar el número completo de la tarjeta.<br><br>Podemos recibir información sobre el estado del pago, importe, moneda, identificador de la operación y datos necesarios para facturación y obligaciones legales.'],
    ['4. Origen de los datos','Los datos se obtienen:<ul><li>Directamente de la persona usuaria al crear una cuenta, completar un formulario o introducir contenidos.</li><li>Del proveedor de autenticación cuando se utiliza el acceso con Google.</li><li>Automáticamente durante el uso, cuando sea necesario para el funcionamiento, la seguridad o el control de límites.</li><li>Del proveedor de pagos, si se contrata un servicio de pago.</li></ul>Con el acceso de Google solo recibimos los datos básicos autorizados necesarios para identificar y crear la cuenta, habitualmente nombre, correo, imagen de perfil e identificador.<br><br>Este acceso no permite leer Gmail, Google Drive, contactos ni otros contenidos de la cuenta de Google.'],
    ['5. Finalidades y bases jurídicas','Tratamos los datos para crear y gestionar la cuenta; prestar las herramientas y guardar proyectos; aplicar límites; proteger cuentas y prevenir fraude; atender consultas; enviar comunicaciones necesarias; informar de novedades con consentimiento; gestionar pagos y facturación; y defender reclamaciones.<br><br>Las bases jurídicas son la ejecución del servicio solicitado o de la relación contractual, el cumplimiento de obligaciones legales, el interés legítimo y, cuando corresponda, el consentimiento.<br><br>Cuando el tratamiento se base en el consentimiento, puedes retirarlo en cualquier momento. Cuando se base en interés legítimo, puedes solicitar información sobre la ponderación y ejercer tu derecho de oposición.'],
    ['6. Carácter obligatorio de los datos','Los campos obligatorios son necesarios para prestar el servicio o responder a la solicitud. Si no los facilitas, puede que no puedas crear una cuenta, guardar proyectos, contactar o utilizar una funcionalidad determinada.<br><br>No estás obligado a facilitar datos para utilizar las funciones disponibles sin registro.'],
    ['7. Destinatarios y proveedores','No vendemos ni cedemos datos personales con fines publicitarios.<br><br>Pueden acceder a los datos, solo cuando sea necesario: proveedores de autenticación y bases de datos como Supabase; Google cuando se elige ese acceso; proveedores de alojamiento, infraestructura, seguridad, correo, formularios o almacenamiento; proveedores de pago y facturación; y asesorías, profesionales jurídicos o administraciones públicas cuando exista obligación legal o sea necesario defender derechos.<br><br>Los proveedores que actúan por cuenta de uncartel.es deben seguir las instrucciones recibidas y aplicar las garantías exigidas.'],
    ['8. Transferencias internacionales','Algunos proveedores pueden estar establecidos o utilizar infraestructura fuera del Espacio Económico Europeo. Cuando exista una transferencia internacional se utilizarán garantías admitidas por el RGPD: decisiones de adecuación, Marco de Privacidad de Datos UE–EE. UU., cláusulas contractuales tipo u otras garantías legales.<br><br>Puedes solicitar más información en <a href="mailto:hola@uncartel.es">hola@uncartel.es</a>.'],
    ['9. Plazos de conservación','La cuenta se conserva mientras esté activa; los proyectos, hasta que se eliminen o se suprima la cuenta; las copias de seguridad, durante su rotación técnica; las consultas, el tiempo necesario y como máximo doce meses tras cerrarlas salvo reclamación; los registros de seguridad, durante el plazo necesario; las comunicaciones comerciales, hasta retirar el consentimiento; y las facturas, pagos y reclamaciones, durante los plazos legales aplicables.<br><br>Al finalizar el plazo, los datos se eliminarán o quedarán bloqueados exclusivamente para cumplir obligaciones legales.'],
    ['10. Derechos de las personas interesadas','Puedes ejercer los derechos de acceso, rectificación, supresión, oposición, limitación, portabilidad, retirada del consentimiento y no ser objeto de decisiones exclusivamente automatizadas con efectos significativos.<br><br>Escribe a <a href="mailto:hola@uncartel.es">hola@uncartel.es</a>, indicando el derecho que quieres ejercer. Solo se pedirá documentación adicional si existen dudas razonables sobre la identidad.<br><br>También puedes reclamar ante la Agencia Española de Protección de Datos: <a href="https://www.aepd.es/">https://www.aepd.es</a>.'],
    ['11. Eliminación de la cuenta','Puedes eliminar la cuenta mediante las opciones habilitadas o solicitarlo en <a href="mailto:hola@uncartel.es">hola@uncartel.es</a>.<br><br>La eliminación supondrá la supresión o anonimización de los datos, salvo aquellos que deban conservarse bloqueados por obligación legal, seguridad, prevención del fraude o defensa de reclamaciones. Es responsabilidad de la persona usuaria descargar antes los proyectos que quiera conservar.'],
    ['12. Comunicaciones comerciales','Solo enviaremos comunicaciones comerciales cuando exista una base jurídica válida, principalmente el consentimiento. Puedes darte de baja mediante el enlace incluido o escribiendo a <a href="mailto:hola@uncartel.es">hola@uncartel.es</a>.<br><br>Los avisos imprescindibles sobre seguridad, cuenta, condiciones o funcionamiento no son comunicaciones comerciales.'],
    ['13. Menores de edad','El servicio no se dirige específicamente a menores de catorce años. Las personas menores de esa edad no deben crear una cuenta ni facilitar datos sin autorización de quien ejerza la patria potestad o tutela. Si se detectan datos sin autorización, podrán eliminarse y bloquearse la cuenta.'],
    ['14. Seguridad','Aplicamos medidas técnicas y organizativas proporcionadas al riesgo. Ningún sistema conectado a Internet puede garantizar una seguridad absoluta. Ante una violación que pueda suponer riesgo para los derechos de las personas, se actuará conforme a las obligaciones del RGPD.'],
    ['15. Decisiones automatizadas','Actualmente no se adoptan decisiones basadas exclusivamente en tratamientos automatizados que produzcan efectos jurídicos o afecten significativamente. Los controles automáticos de descargas, seguridad o acceso se limitan a aplicar el plan y prevenir abusos.'],
    ['16. Enlaces y contenidos públicos','La persona usuaria es responsable de no introducir datos personales de terceros sin base jurídica suficiente. Un documento o enlace compartido públicamente puede ser accesible por cualquiera que disponga de la dirección o del QR; corresponde a la persona usuaria configurar correctamente sus permisos.'],
    ['17. Cambios en esta política','Esta política puede actualizarse por cambios legales, técnicos o funcionales. La versión vigente será la publicada en esta página. Los cambios relevantes se comunicarán mediante la web o por correo electrónico.']
  ];
  const copy={
    ca:{
      faq:{eyebrow:'Ajuda',title:'Preguntes freqüents',intro:'Tot el que cal saber per crear, personalitzar, desar i descarregar els teus projectes.',items:[
        ['Què puc fer sense registrar-me?','Pots utilitzar les eines bàsiques per crear cartells, cartes i menús, cartes de serveis i codis QR. El pla Basic permet editar continguts i fer fins a 10 descàrregues diàries compartides entre totes les eines.'],
        ['Quines eines hi ha disponibles?','Ara mateix pots crear cartells, cartes i menús, cartes de serveis i tarifes, i codis QR. Continuarem incorporant noves eines mantenint el mateix sistema d’edició.'],
        ['Què inclou Premium?','Premium afegeix colors i tipografies personalitzades, descàrregues il·limitades i la possibilitat de desar i recuperar projectes. També desbloqueja els formats mòbils i les funcions Premium indicades a cada eina.'],
        ['Premium és gratuït durant 6 mesos?','Sí. L’activació és gratuïta durant 6 mesos, sense targeta ni renovació automàtica. T’avisarem abans de qualsevol canvi perquè puguis decidir què vols fer.'],
        ['Què inclourà Ultra?','Ultra està pensat per a marques i empreses: permetrà retirar o editar la marca d’aigua, aplicar un kit de marca, utilitzar logotips i imatges i accedir als formats i descàrregues avançats marcats com a Ultra.'],
        ['Per què necessito un compte?','El compte identifica el teu pla i permet desar i recuperar projectes entre sessions. Només demanem les dades imprescindibles per prestar el servei.'],
        ['Com funciona el límit de descàrregues?','Basic disposa de 10 descàrregues diàries compartides entre totes les eines. El comptador es reinicia cada dia. Premium i Ultra tenen descàrregues il·limitades.'],
        ['En quins formats puc descarregar?','Els formats depenen de cada eina. PDF és el format principal per imprimir; PNG és Premium i SVG és Ultra quan apareixen disponibles. Els codis QR també es poden imprimir directament.'],
        ['Puc utilitzar els dissenys al meu negoci?','Sí. Pots utilitzar els documents creats al teu comerç, oficina, escola, equipament o projecte. No està permès revendre les plantilles, redistribuir el catàleg ni presentar el sistema com a propi.'],
        ['Com puc gestionar o eliminar les meves dades?','Des de l’àrea de compte pots modificar el nom, consultar el pla, tancar la sessió o eliminar el compte. També ens pots escriure des de Contacte.']
      ]},
      manifest:{eyebrow:'Manifest',title:'Crec que el bon disseny no hauria de dependre dels diners.',paragraphs:['Fa anys que em dedico a dissenyar informació perquè les persones s’orientin, entenguin millor els espais i es moguin amb més facilitat.','Un cartell, una carta o una tarifa també formen part d’aquesta experiència.','Per això vaig crear <strong>uncartell.cat</strong>: eines gratuïtes, clares i cuidades perquè qualsevol persona pugui crear documents útils i preparar-los per imprimir o compartir.','La versió gratuïta sempre existirà. Si algun dia decideixes fer-te Premium, m’ajudaràs a mantenir aquest projecte i a continuar fent-lo créixer.','<strong>M’acompanyes en aquesta aventura?</strong>']},
      privacy:privacyCa,
      cookies:{eyebrow:'Legal',title:'Política de cookies',intro:'Última actualització: 11 d’agost de 2026.',sections:[['1. Què utilitzem','Fem servir emmagatzematge local i elements tècnics necessaris per conservar la sessió, les preferències, els projectes locals i el recompte diari de descàrregues.'],['2. Categories','Les necessàries permeten la sessió, la seguretat i el funcionament de les eines. Les analítiques serien opcionals i actualment no hi ha cap proveïdor analític actiu. No utilitzem cookies publicitàries.'],['3. Consentiment','Les opcions no necessàries només s’activaran després d’una acceptació expressa. Continuar navegant no es considera consentiment.'],['4. Preferències','Pots canviar o retirar la selecció en qualsevol moment amb el botó “Configura les cookies” del peu del web. Bloquejar elements necessaris pot impedir l’inici de sessió o el desament de preferències.']]},
      legal:legalCa,
      contact:{eyebrow:'Contacte',title:'Escriu-nos.',intro:'Tens dubtes, suggeriments o una idea per a una nova eina? Explica’ns-ho.',name:'Nom',email:'Correu electrònic',message:'Missatge',send:'Envia el missatge',sending:'Enviant…',successTitle:'Enviat!',success:'Hem rebut el missatge. En breus et donarem resposta.',error:'No s’ha pogut enviar. Torna-ho a provar.'}
    },
    es:{
      faq:{eyebrow:'Ayuda',title:'Preguntas frecuentes',intro:'Todo lo que necesitas saber para crear, personalizar, guardar y descargar tus proyectos.',items:[['¿Qué puedo hacer sin registrarme?','Puedes utilizar las herramientas básicas para crear carteles, cartas y menús, cartas de servicios y códigos QR. Basic permite editar contenidos y realizar hasta 10 descargas diarias compartidas entre todas las herramientas.'],['¿Qué herramientas están disponibles?','Actualmente puedes crear carteles, cartas y menús, cartas de servicios y tarifas, y códigos QR. Seguiremos incorporando herramientas con el mismo sistema de edición.'],['¿Qué incluye Premium?','Premium añade colores y tipografías personalizadas, descargas ilimitadas y la posibilidad de guardar y recuperar proyectos. También desbloquea los formatos móviles y las funciones Premium indicadas en cada herramienta.'],['¿Premium es gratuito durante 6 meses?','Sí. La activación es gratuita durante 6 meses, sin tarjeta ni renovación automática. Te avisaremos antes de cualquier cambio.'],['¿Qué incluirá Ultra?','Ultra está pensado para marcas y empresas: permitirá retirar o editar la marca de agua, aplicar un kit de marca, utilizar logotipos e imágenes y acceder a formatos avanzados.'],['¿Por qué necesito una cuenta?','La cuenta identifica tu plan y permite guardar y recuperar proyectos entre sesiones. Solo pedimos los datos imprescindibles.'],['¿Cómo funciona el límite de descargas?','Basic dispone de 10 descargas diarias compartidas entre todas las herramientas. El contador se reinicia cada día. Premium y Ultra tienen descargas ilimitadas.'],['¿En qué formatos puedo descargar?','Los formatos dependen de cada herramienta. PDF es el formato principal para imprimir; PNG es Premium y SVG es Ultra cuando aparecen disponibles.'],['¿Puedo utilizar los diseños en mi negocio?','Sí. Puedes utilizarlos en tu comercio, oficina, centro educativo, equipamiento o proyecto. No está permitido revender las plantillas, redistribuir el catálogo ni presentar el sistema como propio.'],['¿Cómo puedo gestionar o eliminar mis datos?','Desde el área de cuenta puedes modificar el nombre, consultar el plan, cerrar sesión o eliminar la cuenta. También puedes escribirnos desde Contacto.']]},
      manifest:{eyebrow:'Manifiesto',title:'Creo que el buen diseño no debería depender del dinero.',paragraphs:['Desde hace años me dedico a diseñar información para ayudar a las personas a orientarse, comprender mejor los espacios y moverse con más facilidad.','Un cartel, una carta o una tarifa también forman parte de esa experiencia.','Por eso creé <strong>uncartel.es</strong>: herramientas gratuitas, claras y cuidadas para que cualquier persona pueda crear documentos útiles y prepararlos para imprimir o compartir.','La versión gratuita siempre existirá. Si algún día decides hacerte Premium, me ayudarás a mantener este proyecto y a seguir ampliándolo.','<strong>¿Me acompañas en esta aventura?</strong>']},
      privacy:privacyEs,
      cookies:{eyebrow:'Legal',title:'Política de cookies',intro:'Última actualización: 11 de agosto de 2026.',sections:[['1. Qué utilizamos','Utilizamos almacenamiento local y elementos técnicos necesarios para conservar la sesión, las preferencias, los proyectos locales y el recuento diario de descargas.'],['2. Categorías','Las necesarias permiten la sesión, la seguridad y el funcionamiento. Las analíticas serían opcionales y actualmente no hay ningún proveedor analítico activo. No utilizamos cookies publicitarias.'],['3. Consentimiento','Las opciones no necesarias solo se activarán tras una aceptación expresa. Continuar navegando no se considera consentimiento.'],['4. Preferencias','Puedes cambiar o retirar tu selección en cualquier momento desde “Configura las cookies” en el pie de la web.']]},
      legal:legalEs,
      contact:{eyebrow:'Contacto',title:'Escríbenos.',intro:'¿Tienes dudas, sugerencias o una idea para una nueva herramienta? Cuéntanoslo.',name:'Nombre',email:'Correo electrónico',message:'Mensaje',send:'Enviar mensaje',sending:'Enviando…',successTitle:'¡Enviado!',success:'Hemos recibido el mensaje. Te responderemos en breve.',error:'No se ha podido enviar. Inténtalo de nuevo.'}
    }
  };
  const data=copy[lang][key],main=document.querySelector('[data-info-page]');
  document.title=`${data.title} | ${lang==='es'?'uncartel.es':'uncartell.cat'}`;
  const head=`<header class="u-info-head"><span class="u-eyebrow">${data.eyebrow}</span><h1>${data.title}</h1>${data.intro?`<p>${data.intro}</p>`:''}</header>`;
  if(key==='faq')main.innerHTML=`${head}<div class="u-faq-list">${data.items.map(([q,a])=>`<details class="u-faq-item"><summary>${q}</summary><div>${a}</div></details>`).join('')}</div>`;
  else if(key==='manifest')main.innerHTML=`<div class="u-manifest-copy">${head}${data.paragraphs.slice(0,2).map(p=>`<p>${p}</p>`).join('')}<figure class="u-manifest-image"><img src="/manifest-taller.jpg" alt="${lang==='es'?'Documentos creados con uncartel.es':'Documents creats amb uncartell.cat'}"></figure>${data.paragraphs.slice(2).map(p=>`<p>${p}</p>`).join('')}<div class="u-manifest-sign"><img src="/marti-ruiz.jpg" alt="Martí Ruiz"><div><strong>Martí Ruiz</strong><span>${lang==='es'?'Creador de uncartel.es':'Creador d’uncartell.cat'}</span><a href="https://es.linkedin.com/in/marti-ruiz" target="_blank" rel="noopener" aria-label="LinkedIn"><svg viewBox="0 0 24 24"><path d="M6.5 8.5H3.3V19h3.2V8.5ZM4.9 3A1.9 1.9 0 1 0 5 6.8 1.9 1.9 0 0 0 4.9 3ZM12 8.5H8.9V19H12v-5.2c0-1.4.3-2.7 2-2.7s1.7 1.6 1.7 2.8V19H19v-5.8c0-2.9-.6-5-3.9-5a3.4 3.4 0 0 0-3.1 1.7V8.5Z"/></svg></a></div></div></div>`;
  else if(key==='contact'){
    main.innerHTML=`${head}<form class="u-contact-form" data-contact-form><label>${data.name}<input name="name" autocomplete="name" required></label><label>${data.email}<input name="email" type="email" autocomplete="email" required></label><label>${data.message}<textarea name="message" required></textarea></label><button class="u-button primary" type="submit">${data.send}</button><div data-contact-feedback aria-live="polite"></div></form>`;
    const form=main.querySelector('[data-contact-form]'),feedback=main.querySelector('[data-contact-feedback]');
    form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('button');button.disabled=true;button.textContent=data.sending;feedback.textContent='';try{await window.UncartellPlatform.submitMailboxForm({type:'contact',form});form.hidden=true;feedback.className='u-contact-success';feedback.innerHTML=`<span aria-hidden="true">✓</span><div><strong>${data.successTitle}</strong><p>${data.success}</p></div>`}catch(_){feedback.textContent=data.error;button.disabled=false;button.textContent=data.send}});
  }else{
    main.innerHTML=`${head}<div class="u-info-body">${data.sections.map(([h,p])=>`<h2>${h}</h2><p>${p}</p>`).join('')}${key==='cookies'?`<button class="u-button u-cookie-settings-inline" data-info-cookie-settings>${lang==='es'?'Configura las cookies':'Configura les cookies'}</button>`:''}</div>`;
    main.querySelector('[data-info-cookie-settings]')?.addEventListener('click',()=>document.querySelector('.u-footer [data-cookie-settings]')?.click());
  }
})();
